-- One-time adoption of the pre-Manifest Workspace Academy production deployment.
-- Future MCP-enabled deployments are registered automatically by apps-worker.
INSERT INTO apps_app_mcp_manifests (
  id,
  app_id,
  deployment_id,
  schema_version,
  tool_definition_version,
  manifest_sha256,
  manifest_json,
  created_by,
  created_at
)
SELECT
  'mcpmanifest_academy_mcp_1',
  app.id,
  deployment.id,
  'workspace.app-mcp/v1',
  'academy-mcp-1',
  'f4512373368e26874d5e5cf4caa42b2a0b14cbc8723f9f7859331323799fd68c',
  '{"schemaVersion":"workspace.app-mcp/v1","appId":"app_83c1296c08eb","name":"Workspace Academy","description":"Workspace learning videos, SharePoint lessons, and R2-hosted courses.","baseUrl":"https://workspace-academy.example.invalid","audience":"https://workspace-academy.example.invalid","resourceId":"app-mcp:app_83c1296c08eb","toolDefinitionVersion":"academy-mcp-1","authorization":{"model":"app-rbac","defaultRole":"user","toolsEndpoint":"/api/v1/mcp/tools","toolsEndpointScope":"app:mcp:discover","roles":[{"id":"user","name":"User","system":true},{"id":"admin","name":"Content administrator","system":true},{"id":"owner","name":"App owner","system":true}]},"tools":[{"name":"academy_list_videos","description":"List published Workspace Academy videos and their department/category metadata.","method":"GET","path":"/api/v1/academy","allowedRoles":["user","admin","owner"],"requiredScopes":["academy:read"],"readOnly":true,"riskLevel":"low","requiresConfirmation":false,"inputSchema":{"type":"object","properties":{},"additionalProperties":false}},{"name":"academy_create_video","description":"Create draft video metadata for either an R2 upload or a validated SharePoint link.","method":"POST","path":"/api/v1/admin/videos","allowedRoles":["admin","owner"],"requiredScopes":["academy:write"],"readOnly":false,"riskLevel":"medium","requiresConfirmation":true,"inputSchema":{"type":"object","required":["slug","provider","titleZh"],"additionalProperties":false,"properties":{"slug":{"type":"string","pattern":"^[a-z0-9]+(?:-[a-z0-9]+)*$","maxLength":100},"provider":{"type":"string","enum":["r2","sharepoint"]},"titleZh":{"type":"string","maxLength":240},"titleEn":{"type":"string","maxLength":240},"summaryZh":{"type":"string","maxLength":4000},"summaryEn":{"type":"string","maxLength":4000},"categoryId":{"type":"string","maxLength":120},"departmentId":{"type":"string","maxLength":120},"sharepointUrl":{"type":"string","maxLength":4000},"durationSeconds":{"type":"integer","minimum":1,"maximum":43200}}}},{"name":"academy_update_video","description":"Update Academy video metadata without changing its storage provider or publication state.","method":"POST","path":"/api/v1/admin/videos/update","allowedRoles":["admin","owner"],"requiredScopes":["academy:write"],"readOnly":false,"riskLevel":"medium","requiresConfirmation":true,"inputSchema":{"type":"object","required":["videoId"],"additionalProperties":false,"properties":{"videoId":{"type":"string","maxLength":100},"titleZh":{"type":"string","maxLength":240},"titleEn":{"type":["string","null"],"maxLength":240},"summaryZh":{"type":["string","null"],"maxLength":4000},"summaryEn":{"type":["string","null"],"maxLength":4000},"categoryId":{"type":["string","null"],"maxLength":120},"departmentId":{"type":["string","null"],"maxLength":120},"coverUrl":{"type":["string","null"],"maxLength":2000},"sharepointUrl":{"type":"string","maxLength":4000},"durationSeconds":{"type":["integer","null"],"minimum":1,"maximum":43200},"featuredRank":{"type":["integer","null"],"minimum":1,"maximum":100}}}},{"name":"academy_begin_r2_upload","description":"Create a short-lived presigned PUT URL. The caller uploads the video bytes directly to R2; bytes never pass through MCP JSON or the Academy Worker.","method":"POST","path":"/api/v1/admin/uploads/begin","allowedRoles":["admin","owner"],"requiredScopes":["academy:write"],"readOnly":false,"riskLevel":"medium","requiresConfirmation":true,"inputSchema":{"type":"object","required":["videoId","fileName","mimeType","sizeBytes"],"additionalProperties":false,"properties":{"videoId":{"type":"string","maxLength":100},"fileName":{"type":"string","maxLength":200},"mimeType":{"type":"string","enum":["video/mp4","video/webm"]},"sizeBytes":{"type":"integer","minimum":1,"maximum":5368709120}}}},{"name":"academy_complete_r2_upload","description":"Verify a direct R2 upload and attach the object to its draft video.","method":"POST","path":"/api/v1/admin/uploads/complete","allowedRoles":["admin","owner"],"requiredScopes":["academy:write"],"readOnly":false,"riskLevel":"medium","requiresConfirmation":true,"inputSchema":{"type":"object","required":["uploadId"],"additionalProperties":false,"properties":{"uploadId":{"type":"string","maxLength":100}}}},{"name":"academy_publish_video","description":"Publish a completed Academy video to all authenticated Workspace users.","method":"POST","path":"/api/v1/admin/videos/publish","allowedRoles":["admin","owner"],"requiredScopes":["academy:write"],"readOnly":false,"riskLevel":"high","requiresConfirmation":true,"inputSchema":{"type":"object","required":["videoId"],"additionalProperties":false,"properties":{"videoId":{"type":"string","maxLength":100}}}},{"name":"academy_archive_video","description":"Archive a video so it leaves the catalog while retaining metadata and any R2 object.","method":"POST","path":"/api/v1/admin/videos/archive","allowedRoles":["admin","owner"],"requiredScopes":["academy:write"],"readOnly":false,"riskLevel":"high","requiresConfirmation":true,"inputSchema":{"type":"object","required":["videoId"],"additionalProperties":false,"properties":{"videoId":{"type":"string","maxLength":100}}}},{"name":"academy_save_category","description":"Create or update an Academy content category.","method":"POST","path":"/api/v1/admin/categories","allowedRoles":["admin","owner"],"requiredScopes":["academy:write"],"readOnly":false,"riskLevel":"medium","requiresConfirmation":true,"inputSchema":{"type":"object","required":["slug","nameZh","nameEn"],"additionalProperties":false,"properties":{"id":{"type":"string","maxLength":100},"slug":{"type":"string","maxLength":100},"nameZh":{"type":"string","maxLength":120},"nameEn":{"type":"string","maxLength":120},"description":{"type":"string","maxLength":1000},"departmentId":{"type":"string","maxLength":120},"parentId":{"type":"string","maxLength":120},"sortOrder":{"type":"integer","minimum":0,"maximum":10000},"active":{"type":"boolean"}}}},{"name":"academy_save_department","description":"Save Academy display settings for an immutable Workspace department ID.","method":"POST","path":"/api/v1/admin/departments","allowedRoles":["owner"],"requiredScopes":["academy:admin"],"readOnly":false,"riskLevel":"medium","requiresConfirmation":true,"inputSchema":{"type":"object","required":["id","name"],"additionalProperties":false,"properties":{"id":{"type":"string","maxLength":120},"name":{"type":"string","maxLength":160},"description":{"type":"string","maxLength":1000},"parentId":{"type":"string","maxLength":120},"accent":{"type":"string","pattern":"^#[0-9a-fA-F]{6}$"},"sortOrder":{"type":"integer","minimum":0,"maximum":10000},"active":{"type":"boolean"}}}},{"name":"academy_sync_departments","description":"Refresh Academy department choices from the App-policy-filtered Workspace Auth directory.","method":"POST","path":"/api/v1/admin/departments/sync","allowedRoles":["owner"],"requiredScopes":["academy:admin"],"readOnly":false,"riskLevel":"medium","requiresConfirmation":true,"inputSchema":{"type":"object","properties":{},"additionalProperties":false}},{"name":"academy_set_collaborator_role","description":"Assign an app-local viewer, collaborator, or owner role after that employee has signed in once.","method":"POST","path":"/api/v1/admin/collaborators","allowedRoles":["owner"],"requiredScopes":["academy:admin"],"readOnly":false,"riskLevel":"high","requiresConfirmation":true,"inputSchema":{"type":"object","required":["userId","role"],"additionalProperties":false,"properties":{"userId":{"type":"string","maxLength":160},"role":{"type":"string","enum":["viewer","collaborator","owner"]}}}}]}',
  app.owner_user_id,
  CURRENT_TIMESTAMP
FROM apps_apps AS app
JOIN apps_deployments AS deployment
  ON deployment.app_id = app.id
 AND deployment.environment = 'production'
 AND deployment.status = 'published'
WHERE app.id = 'app_83c1296c08eb'
  AND app.agent_mcp_enabled = 1
ORDER BY deployment.created_at DESC
LIMIT 1
ON CONFLICT(id) DO UPDATE SET
  deployment_id = excluded.deployment_id,
  schema_version = excluded.schema_version,
  tool_definition_version = excluded.tool_definition_version,
  manifest_sha256 = excluded.manifest_sha256,
  manifest_json = excluded.manifest_json,
  created_by = excluded.created_by,
  created_at = excluded.created_at;
